import os
for f in sorted(os.listdir('.')):
    t=open(f,encoding='utf-8',errors='replace').read()
    lines=t.split('\n')
    print('=====',f,'lines:',len(lines))
    for i,l in enumerate(lines):
        if 'The code' in l or 'Project' in l or 'Falcon' in l or 'Suzhou' in l:
            print(i, repr(l))
            print('  prev:', repr(lines[i-1]) if i>0 else None)
            print('  next:', repr(lines[i+1]) if i+1<len(lines) else None)

